<?php
namespace App\Controllers;
use App\Core\{Auth,View,Database,Request,Csrf,Response};
use App\Services\{PermissionService,WorkflowEngine,RequirementEngine,ActivityService,AutomationService};
final class ServiceController{
 public function index():void{Auth::requireLogin();(new PermissionService)->require('Service','view');$s=Database::pdo()->query('SELECT s.*,COUNT(cs.id) request_count FROM services s LEFT JOIN client_services cs ON cs.service_id=s.id AND cs.status NOT IN ("completed","cancelled") WHERE s.tenant_id=1 AND s.is_active=1 GROUP BY s.id ORDER BY s.name')->fetchAll();View::render('services/index',['services'=>$s]);}
 public function create():void{Auth::requireLogin();(new PermissionService)->require('Service','configure');View::render('services/form');}
 public function store():never{
  Auth::requireLogin();(new PermissionService)->require('Service','configure');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}
  $pdo=Database::pdo();$pdo->beginTransaction();try{
   $s=$pdo->prepare('INSERT INTO services(tenant_id,name,category,description,price,approval_level,automation_enabled,is_active,created_at,updated_at) VALUES(1,?,?,?,?,?,?,1,NOW(),NOW())');$s->execute([$r->input('name'),$r->input('category'),$r->input('description'),(float)$r->input('price',0),(int)$r->input('approval_level',2),!empty($r->input('automation_enabled'))?1:0]);$id=(int)$pdo->lastInsertId();
   $pdo->prepare('INSERT INTO workflow_versions(service_id,version_no,name,status,created_at) VALUES(?,1,?,"published",NOW())')->execute([$id,$r->input('name').' Workflow v1']);$version=(int)$pdo->lastInsertId();
   $steps=[['Collect Client Information','client_information','required',1,'{"show_initials":true}'],['Collect Required Documents','document_upload','required',2,'{"allow_multiple":true}'],['Validate Requirements','validation','required',3,'{"automatic":true}'],['Professional Review','approval','required',4,'{"approval_level":2}'],['Client Confirmation','client_approval','conditional',5,'{"required_for_levels":[3]}'],['Prepare Filing / Deliverable','preparation','required',6,'{}'],['Submission / Delivery','submission','required',7,'{"external_adapter":"manual_until_configured"}'],['Completion & Follow-up','completion','required',8,'{"create_follow_up":true}']];
   $x=$pdo->prepare('INSERT INTO workflow_steps(workflow_version_id,title,step_type,requirement,sort_order,config_json,created_at) VALUES(?,?,?,?,?,?,NOW())');foreach($steps as $st)$x->execute([$version,$st[0],$st[1],$st[2],$st[3],$st[4]]);
   $pdo->prepare('INSERT INTO service_automation_profiles(service_id,auto_contact_missing,preferred_channel,voice_after_days,max_voice_attempts,minimum_ai_confidence,approval_level) VALUES(?,?,?,?,?,?,?)')->execute([$id,1,'email',2,2,0.85,(int)$r->input('approval_level',2)]);
   $pdo->prepare('INSERT INTO service_requirements(service_id,name,kind,reason,instructions,required,sort_order,is_active) VALUES(?,?,?,?,?,1,?,1)')->execute([$id,'Client authorization','authorization','Required before professional processing.','Record client authorization through the approved CRM/portal process.',0]);
   (new ActivityService)->record('SERVICE_CREATED','Services','service',$id,null,'stage_3');$pdo->commit();Response::redirect(route('service.view',['id'=>$id]));
  }catch(\Throwable $e){$pdo->rollBack();throw $e;}
 }
 public function show($id):void{Auth::requireLogin();$s=Database::pdo()->prepare('SELECT * FROM services WHERE id=?');$s->execute([(int)$id]);$service=$s->fetch();if(!$service){http_response_code(404);exit('Service not found');}$r=Database::pdo()->prepare('SELECT * FROM service_requirements WHERE service_id=? AND is_active=1 ORDER BY sort_order,id');$r->execute([(int)$id]);$w=Database::pdo()->prepare('SELECT * FROM workflow_versions WHERE service_id=? ORDER BY version_no DESC');$w->execute([(int)$id]);View::render('services/show',['service'=>$service,'requirements'=>$r->fetchAll(),'workflows'=>$w->fetchAll(),'clients'=>Database::pdo()->query('SELECT id,full_name FROM clients WHERE deleted_at IS NULL ORDER BY full_name LIMIT 500')->fetchAll()]);}
 public function edit($id):void{Auth::requireLogin();(new PermissionService)->require('Service','configure');$s=Database::pdo()->prepare('SELECT * FROM services WHERE id=?');$s->execute([(int)$id]);View::render('services/form',['service'=>$s->fetch()]);}
 public function update($id):never{Auth::requireLogin();(new PermissionService)->require('Service','configure');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}$before=Database::pdo()->prepare('SELECT * FROM services WHERE id=?');$before->execute([(int)$id]);$b=$before->fetch();Database::pdo()->prepare('UPDATE services SET name=?,category=?,description=?,price=?,approval_level=?,automation_enabled=?,updated_at=NOW() WHERE id=?')->execute([$r->input('name'),$r->input('category'),$r->input('description'),(float)$r->input('price',0),(int)$r->input('approval_level',2),!empty($r->input('automation_enabled'))?1:0,(int)$id]);$after=Database::pdo()->prepare('SELECT * FROM services WHERE id=?');$after->execute([(int)$id]);$a=$after->fetch();(new ActivityService)->record('SERVICE_UPDATED','Services','service',(int)$id,(new ActivityService)->diff($b,$a),'stage_3');Response::redirect(route('service.view',['id'=>$id]));}
 public function workflow($id):void{Auth::requireLogin();(new PermissionService)->require('Service','configure');$s=Database::pdo()->prepare('SELECT * FROM services WHERE id=?');$s->execute([(int)$id]);$service=$s->fetch();$v=Database::pdo()->prepare('SELECT * FROM workflow_versions WHERE service_id=? ORDER BY version_no DESC LIMIT 1');$v->execute([(int)$id]);$version=$v->fetch();$steps=[];if($version){$x=Database::pdo()->prepare('SELECT * FROM workflow_steps WHERE workflow_version_id=? ORDER BY sort_order,id');$x->execute([$version['id']]);$steps=$x->fetchAll();}View::render('services/workflow',['service'=>$service,'version'=>$version,'steps'=>$steps]);}
 public function workflowStepStore($id):never{Auth::requireLogin();(new PermissionService)->require('Service','configure');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}$v=Database::pdo()->prepare('SELECT id FROM workflow_versions WHERE service_id=? ORDER BY version_no DESC LIMIT 1');$v->execute([(int)$id]);$version=$v->fetch();if(!$version)throw new \RuntimeException('No workflow version');$sort=(int)$r->input('sort_order',99);Database::pdo()->prepare('INSERT INTO workflow_steps(workflow_version_id,title,step_type,requirement,sort_order,config_json,created_at) VALUES(?,?,?,?,?,?,NOW())')->execute([$version['id'],$r->input('title'),$r->input('step_type','checkbox'),$r->input('requirement','required'),$sort,$r->input('config_json')?:null]);(new ActivityService)->record('WORKFLOW_STEP_CREATED','Services','service',(int)$id,['title'=>$r->input('title')],'stage_3');Response::redirect(route('service.workflow',['id'=>$id]));}
 public function request():never{Auth::requireLogin();(new PermissionService)->require('Service','request');$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}$clientId=(int)$r->input('client_id');$serviceId=(int)$r->input('service_id');$start=$r->input('start_date',date('Y-m-d'));$end=$r->input('end_date',date('Y-m-d',strtotime('+30 days')));$status=$start>date('Y-m-d')?'upcoming':'open';$pdo=Database::pdo();$pdo->beginTransaction();try{$pdo->prepare('INSERT INTO projects(tenant_id,client_id,business_id,service_id,name,start_date,end_date,status,created_by,created_at,updated_at) VALUES(1,?,?,?,?,?,?,?, ?,NOW(),NOW())')->execute([$clientId,$r->input('business_id')?:null,$serviceId,$r->input('project_name','Service Project'),$start,$end,$status,Auth::id()]);$projectId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO client_services(tenant_id,client_id,service_id,business_id,project_id,status,created_at) VALUES(1,?,?,?,?,'requested',NOW())")->execute([$clientId,$serviceId,$r->input('business_id')?:null,$projectId]);$csId=(int)$pdo->lastInsertId();(new WorkflowEngine)->startForProject($projectId,$serviceId);$pdo->commit();(new ActivityService)->record('SERVICE_REQUESTED','Services','client_service',$csId,['project_id'=>$projectId]);(new AutomationService)->dispatch('SERVICE_REQUESTED',['client_id'=>$clientId,'service_id'=>$serviceId,'project_id'=>$projectId]);Response::redirect(route('client.service.requirements',['id'=>$csId]));}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
 public function requirements($id):void{Auth::requireLogin();$m=(new RequirementEngine)->missing((int)$id);$s=Database::pdo()->prepare('SELECT cs.*,c.full_name,sv.name service_name FROM client_services cs JOIN clients c ON c.id=cs.client_id JOIN services sv ON sv.id=cs.service_id WHERE cs.id=?');$s->execute([(int)$id]);View::render('services/requirements',['requirements'=>$m,'clientService'=>$s->fetch(),'clientServiceId'=>$id]);}
 public function satisfyRequirement($id):never{Auth::requireLogin();$r=new Request;if(!Csrf::check($r->input('_csrf'))){http_response_code(419);exit('CSRF');}$req=(int)$r->input('requirement_id');Database::pdo()->prepare("INSERT INTO requirement_completions(client_service_id,service_id_requirement_id,status,value_json,completed_by,completed_at) VALUES(?,?, 'satisfied',?,?,NOW()) ON DUPLICATE KEY UPDATE status='satisfied',value_json=VALUES(value_json),completed_by=VALUES(completed_by),completed_at=NOW()")->execute([(int)$id,$req,$r->input('value')?json_encode(['value'=>$r->input('value')]):null,Auth::id()]);(new ActivityService)->record('REQUIREMENT_SATISFIED','Services','client_service',(int)$id,['requirement_id'=>$req]);Response::redirect(route('client.service.requirements',['id'=>$id]));}
}
